<script setup lang="ts">
import { onMounted, ref } from 'vue'
import * as api from '../domain/api'
const emit=defineEmits<{ changed: [] }>();const data=ref<api.StaffPage>({items:[],roles:[]});const error=ref('');const busy=ref(false);const create=ref(false);const form=ref({login:'',name:'',password:'',role:'ukm_catalog_editor'})
async function load(){try{data.value=await api.getStaff()}catch(e){error.value=e instanceof Error?e.message:'Ошибка загрузки'}}onMounted(load)
async function add(){busy.value=true;error.value='';try{const payload={...form.value};form.value.password='';await api.addStaff(payload);form.value={login:'',name:'',password:'',role:'ukm_catalog_editor'};create.value=false;await load();emit('changed')}catch(e){error.value=e instanceof Error?e.message:'Не удалось добавить'}finally{busy.value=false}}
async function save(member:api.StaffMember){busy.value=true;error.value='';try{await api.updateStaff(member);await load();emit('changed')}catch(e){error.value=e instanceof Error?e.message:'Не удалось сохранить';await load()}finally{busy.value=false}}
</script>
<template><section><div class="page-heading"><div><h1>Сотрудники</h1><p>Доступ к программе и права на каталог</p></div><button class="button primary" @click="create=!create">＋ Добавить сотрудника</button></div><p v-if="error" class="error-notice" role="alert">{{ error }}</p><form v-if="create" class="settings-card" @submit.prevent="add"><h2>Новая учётная запись</h2><div class="settings-grid"><label>Имя<input v-model="form.name" required /></label><label>Логин<input v-model="form.login" autocomplete="off" required minlength="3" /></label><label>Пароль<input v-model="form.password" type="password" autocomplete="new-password" required minlength="12" placeholder="Не меньше 12 символов" /></label><label>Роль<select v-model="form.role"><option v-for="r in data.roles" :key="r.id" :value="r.id">{{ r.name }}</option></select></label></div><p class="muted">Пароль задаётся при создании, не отображается в списке и не записывается в журнал.</p><button class="button primary" type="submit" :disabled="busy">Создать сотрудника</button></form><div class="info-box"><p>Просмотр — чтение каталога. Редактор — товары, фото, характеристики и фильтры. Управляющий — те же действия и управление сотрудниками. Отключение закрывает действующие сессии.</p></div><div class="staff-list"><form v-for="member in data.items" :key="member.id" class="settings-card" @submit.prevent="save(member)"><div class="settings-grid"><label>Имя сотрудника<input v-model="member.name" /></label><label>Логин<input :value="member.login" readonly /></label><label>Роль<select v-model="member.role"><option v-for="r in data.roles" :key="r.id" :value="r.id">{{ r.name }}</option></select></label><label class="check-label"><input v-model="member.active" type="checkbox" />Доступ включён</label></div><button type="submit" class="button" :disabled="busy">Сохранить права</button></form></div></section></template>
